1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"strings"
10	)
11	
12	// resetHalfWayAdvice ends the Check of every error a reset returns after its first
13	// deletion: what was deleted stays deleted, and running the reset again starts over.
14	const resetHalfWayAdvice = "the reset stopped half-way: run `mise run nexus-bench:reset` again, it starts over"
15	
16	// errRepositoriesNeverEmpty marks the failure of waitRepositoriesEmpty that is not
17	// cured by running the reset again.
18	var errRepositoriesNeverEmpty = errors.New("the repositories never emptied")
19	
20	// storedPasswordOnly is the InitialPassword of a reset: it never reads the pod, so
21	// Provision uses the stored admin password and changes no password.
22	type storedPasswordOnly struct{}
23	
24	// Read reports that there is no initial password.
25	func (storedPasswordOnly) Read(context.Context) (string, bool, error) { return "", false, nil }
26	
27	// Reset brings the data set of the bench back to its initial state without
28	// recreating the instance (CA7): no namespace, Nexus pod or nexus-data write. It
29	// runs RunPreflight(OpReset) itself, as Destroy does, because what it deletes
30	// cannot be undone. It never reads the initial password of the pod and never
31	// changes a password: a bench whose stored admin password is refused, or whose
32	// claim of the upstream the bench did not create, is left untouched.
33	//
34	// The order is: preflight, custom upstream, loopback origin, stored credentials
35	// (checked by one admin read), label of the claim, then the deletion of
36	// docker-group, docker-proxy and docker-hosted, the recycling of the upstream
37	// storage, Provision, the wait for the two repositories to list nothing (H-REPODEL)
38	// and Seed. A failure after the first deletion carries resetHalfWayAdvice, but the
39	// repositories that never empty. Every failure is a *BenchError, but a cancelled
40	// context, which is returned as is. A nil out discards the progress lines.
41	func Reset(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) (ProvisionResult, SeedResult, error) {
42		var none ProvisionResult
43		if out == nil {
44			out = io.Discard
45		}
46		say := func(format string, args ...any) { _, _ = fmt.Fprintf(out, "reset: "+format+"\n", args...) }
47		if err := ctx.Err(); err != nil {
48			return none, SeedResult{}, err
49		}
50		if _, err := RunPreflight(ctx, d.Runner, p, OpReset); err != nil {
51			if cerr := ctx.Err(); cerr != nil {
52				return none, SeedResult{}, cerr
53			}
54			return none, SeedResult{}, err
55		}
56		if !p.UpstreamIsBench() {
57			return none, SeedResult{}, customUpstreamError(p)
58		}
59		if err := requireLoopbackBase(baseURL); err != nil {
60			return none, SeedResult{}, err
61		}
62		_, _, c, err := seedCredentials(ctx, d.Store, baseURL)
63		if err != nil {
64			return none, SeedResult{}, err
65		}
66		defer c.closeIdle()
67		if err := c.requireAdmin(ctx); err != nil {
68			if cerr := ctx.Err(); cerr != nil {
69				return none, SeedResult{}, cerr
70			}
71			return none, SeedResult{}, asBenchError(err, p, baseURL)
72		}
73		dep := &deployer{pf: preflight{r: d.Runner, p: p}, w: upstreamWorkload(), tag: "upstream", clk: d.Clock, out: out}
74		if _, _, err := dep.checkedUpstreamClaim(ctx); err != nil {
75			return none, SeedResult{}, err
76		}
77	
78		// halfWay returns err with the advice to run the reset again, once something
79		// was deleted.
80		halfWay := func(err error) (ProvisionResult, SeedResult, error) {
81			if cerr := ctx.Err(); cerr != nil {
82				return none, SeedResult{}, cerr
83			}
84			var be *BenchError
85			if !errors.As(err, &be) {
86				return none, SeedResult{}, err
87			}
88			half := *be
89			half.Check = be.Check + ". " + resetHalfWayAdvice
90			return none, SeedResult{}, &half
91		}
92	
93		say("deleting the repositories %s", strings.Join(benchRepositories, ", "))
94		for _, name := range benchRepositories {
95			if _, err := c.deleteRepository(ctx, name); err != nil {
96				return halfWay(asBenchError(err, p, baseURL))
97			}
98		}
99		say("replacing the storage of the upstream")
100		if err := recycleUpstreamStorage(ctx, d.Runner, d.Clock, p, out); err != nil {
101			return halfWay(err)
102		}
103		prov, err := Provision(ctx, baseURL, storedPasswordOnly{}, d.Store, p, out)
104		if err != nil {
105			return halfWay(err)
106		}
107		say("waiting for %s and %s to list nothing", dockerHostedRepository, dockerProxyRepository)
108		if err := waitRepositoriesEmpty(ctx, c, d.Clock, dockerHostedRepository, dockerProxyRepository); err != nil {
109			if errors.Is(err, errRepositoriesNeverEmpty) {
110				return none, SeedResult{}, err
111			}
112			return halfWay(asBenchError(err, p, baseURL))
113		}
114		seed, err := Seed(ctx, d, baseURL, p, out)
115		if err != nil {
116			return halfWay(err)
117		}
118		say("the bench is back to its initial state")
119		return prov, seed, nil
120	}
121	
122	// waitRepositoriesEmpty polls the repositories until none lists a component, for at
123	// most seedListWait (H-REPODEL): the deletion of a repository empties its storage
124	// in the background. Like the other waits, it looks at the deadline after a
125	// reading. The repositories that still list something are named in a SeedFailed
126	// error that points at the log of the pod, as running the reset again would wait
127	// for the same thing.
128	func waitRepositoriesEmpty(ctx context.Context, c *client, clk Clock, repos ...string) error {
129		deadline := clk.Now().Add(seedListWait)
130		for {
131			var left []string
132			for _, repo := range repos {
133				comps, err := c.listComponents(ctx, repo)
134				if err != nil {
135					return err
136				}
137				for _, comp := range comps {
138					left = append(left, repo+": "+comp.Name+":"+comp.Version)
139				}
140			}
141			if len(left) == 0 {
142				return nil
143			}
144			if !clk.Now().Before(deadline) {
145				return &BenchError{
146					Kind:  SeedFailed,
147					Cause: fmt.Sprintf("the repositories still list components after %s: %s", seedListWait, shownNames(left)),
148					Check: "read the log of the Nexus pod (kubectl logs deploy/nexus): the deletion of a repository did not empty its storage",
149					Err:   errRepositoriesNeverEmpty,
150				}
151			}
152			if err := clk.Sleep(ctx, seedListInterval); err != nil {
153				return err
154			}
155		}
156	}
157	
158	// recycleUpstreamStorage empties the upstream registry by replacing its claim:
159	// the upstream is cut, the claim bench-upstream-data (and nothing else) is
160	// deleted once its label is checked, recreated from its manifest alone, and the
161	// upstream is brought back to one ready replica. The delete is sent once and never
162	// retried; the wait for the claim to be gone lasts until Params.DeleteTimeout.
163	// Like CutUpstream, it runs no preflight (the caller runs OpReset), refuses a
164	// custom upstream before any call, returns a cancelled context as is and accepts
165	// a nil out. A claim that is already gone is not deleted again, so a run that
166	// stopped between the delete and the apply starts again where it stopped.
167	func recycleUpstreamStorage(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
168		if out == nil {
169			out = io.Discard
170		}
171		if err := CutUpstream(ctx, r, clk, p, out); err != nil {
172			return err
173		}
174		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
175		if err := d.deleteUpstreamClaim(ctx); err != nil {
176			return err
177		}
178		claim, err := renderUpstreamClaim(p)
179		if err != nil {
180			return err
181		}
182		d.say("creating the claim %s again", upstreamClaimName)
183		if err := d.apply(ctx, "the claim "+upstreamClaimName, claim); err != nil {
184			return err
185		}
186		return EnsureUpstream(ctx, r, clk, p, out)
187	}
188	
189	// checkedUpstreamClaim reads the claim of the upstream and checks that its label
190	// proves the bench created it; found is false when the claim is not there. It
191	// returns the UID of the claim it read.
192	func (d *deployer) checkedUpstreamClaim(ctx context.Context) (uid string, found bool, err error) {
193		uid, labels, found, err := d.readUpstreamClaim(ctx)
194		if err != nil || !found {
195			return "", found, err
196		}
197		if labels[managedByLabel] != managedByValue {
198			return "", true, &BenchError{
199				Kind:  Unclassified,
200				Cause: fmt.Sprintf("the claim %s does not carry the label %s=%s, so the bench did not create it and will not delete it", upstreamClaimName, managedByLabel, managedByValue),
201				Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "--show-labels"),
202			}
203		}
204		return uid, true, nil
205	}
206	
207	// deleteUpstreamClaim deletes the claim of the upstream, once its label proves
208	// the bench created it, and waits until it is gone. A claim that is not there is
209	// left as it is. The delete carries a precondition on the UID that was read, so a
210	// claim replaced since the read is not deleted: kubectl has no flag for it, hence
211	// the raw form with a DeleteOptions body.
212	func (d *deployer) deleteUpstreamClaim(ctx context.Context) error {
213		uid, found, err := d.checkedUpstreamClaim(ctx)
214		if err != nil || !found {
215			return err
216		}
217		body, err := json.Marshal(map[string]any{
218			"kind":          "DeleteOptions",
219			"apiVersion":    "v1",
220			"preconditions": map[string]string{"uid": uid},
221		})
222		if err != nil {
223			return err
224		}
225		d.say("deleting the claim %s", upstreamClaimName)
226		path := "/api/v1/namespaces/" + d.pf.p.Namespace + "/persistentvolumeclaims/" + upstreamClaimName
227		args := []string{"delete", "--raw", path, "-f", "-", applyTimeout}
228		if _, errOut, err := d.pf.r.Run(ctx, body, args...); err != nil {
229			if cerr := ctx.Err(); cerr != nil {
230				return cerr
231			}
232			return d.pf.failure("delete the claim "+upstreamClaimName, args, string(errOut), err)
233		}
234		return d.waitUpstreamClaimGone(ctx)
235	}
236	
237	// readUpstreamClaim reads the claim of the upstream by name; found is false when
238	// it is not there.
239	func (d *deployer) readUpstreamClaim(ctx context.Context) (uid string, labels map[string]string, found bool, err error) {
240		var claim struct {
241			Metadata struct {
242				UID    string            `json:"uid"`
243				Labels map[string]string `json:"labels"`
244			} `json:"metadata"`
245		}
246		args := []string{"get", "pvc", upstreamClaimName, "-n", d.pf.p.Namespace, "-o", "json"}
247		found, err = d.fetch(ctx, "read the claim "+upstreamClaimName, args, &claim, true)
248		return claim.Metadata.UID, claim.Metadata.Labels, found, err
249	}
250	
251	// waitUpstreamClaimGone polls the claim until it is not there, or until
252	// Params.DeleteTimeout passes. Like the other waits, it looks at the deadline
253	// after a reading.
254	func (d *deployer) waitUpstreamClaimGone(ctx context.Context) error {
255		p := d.pf.p
256		deadline := d.clk.Now().Add(p.DeleteTimeout)
257		for {
258			_, _, found, err := d.readUpstreamClaim(ctx)
259			if err != nil || !found {
260				return err
261			}
262			if !d.clk.Now().Before(deadline) {
263				return &BenchError{
264					Kind:  Deadline,
265					Cause: fmt.Sprintf("the claim %s is still terminating after %s: a finalizer (kubernetes.io/pvc-protection) may hold it", upstreamClaimName, p.DeleteTimeout),
266					Check: d.pf.command("get", "pvc", upstreamClaimName, "-n", p.Namespace, "-o", "yaml"),
267				}
268			}
269			if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
270				return err
271			}
272		}
273	}
274

1	package nexusbench
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8	)
9	
10	// RestoreUpstream brings a cut upstream back (CA4): one ready replica, the proxy
11	// put back in service, the upstream images checked against the data set through a
12	// port-forward, and the cached images read once through docker-proxy, which
13	// refreshes the cache the unblock emptied (H-STALE). It never copies an image,
14	// never writes the cluster but the scale of the upstream, and never reads a
15	// non-PullThrough image through docker-proxy (F9). The stored credentials are
16	// read before anything is written. It runs no preflight (the caller runs
17	// OpRestore) and refuses a REST origin that is not the loopback. Every failure is
18	// a *BenchError, but a cancelled context, which is returned as is. A nil out
19	// discards the progress lines.
20	func RestoreUpstream(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) error {
21		if out == nil {
22			out = io.Discard
23		}
24		if err := ctx.Err(); err != nil {
25			return err
26		}
27		if !p.UpstreamIsBench() {
28			return customUpstreamError(p)
29		}
30		if err := requireLoopbackBase(baseURL); err != nil {
31			return err
32		}
33		_, pull, c, err := seedCredentials(ctx, d.Store, baseURL)
34		if err != nil {
35			return err
36		}
37		defer c.closeIdle()
38		if err := EnsureUpstream(ctx, d.Runner, d.Clock, p, out); err != nil {
39			return err
40		}
41		if err := putProxyBack(ctx, c, baseURL, p, out); err != nil {
42			return err
43		}
44		images := Dataset()
45		if err := verifyUpstreamImages(ctx, d, p, images, out); err != nil {
46			return err
47		}
48		return verifyProxyImages(ctx, d, p, images, pull, out)
49	}
50	
51	// verifyUpstreamImages reads each image of the upstream through a port-forward,
52	// with no credential, and checks its digest against the data set. The
53	// port-forward is stopped before it returns.
54	func verifyUpstreamImages(ctx context.Context, d SeedDeps, p Params, images []DatasetImage, out io.Writer) error {
55		local, stop, err := d.Forwarder.Forward(ctx, p.Namespace, upstreamServiceName, upstreamServicePort)
56		if err != nil {
57			return stepFailure(ctx, err, "the port-forward to the upstream")
58		}
59		if stop != nil {
60			defer func() { _ = stop() }()
61		}
62		if err := checkLoopbackForward(local); err != nil {
63			return err
64		}
65		for _, img := range images {
66			if img.Location != LocationUpstream {
67				continue
68			}
69			name := img.Name + ":" + img.Tag
70			have, err := d.Copier.ManifestDigest(ctx, upstreamImageRef(local, img), nil)
71			if errors.Is(err, errImageAbsent) {
72				return &BenchError{Kind: SeedFailed, Cause: "the upstream lost " + name, Check: resetCheck}
73			}
74			if err != nil {
75				return stepFailure(ctx, err, "reading "+name+" in the upstream")
76			}
77			if have != img.Digest {
78				return &BenchError{Kind: SeedFailed, Cause: "the upstream holds another content for " + name, Check: resetCheck}
79			}
80		}
81		_, _ = fmt.Fprintln(out, "restore: the upstream holds the data set")
82		return nil
83	}
84	
85	// verifyProxyImages reads the PullThrough images through docker-proxy with the
86	// bench-pull account and checks their digests against the data set.
87	func verifyProxyImages(ctx context.Context, d SeedDeps, p Params, images []DatasetImage, pull Credentials, out io.Writer) error {
88		for _, img := range images {
89			if !img.PullThrough {
90				continue
91			}
92			name := img.Name + ":" + img.Tag
93			have, err := d.Copier.ManifestDigest(ctx, nexusImageRef(p, dockerProxyRepository, img), &pull)
94			if err != nil {
95				return stepFailure(ctx, err, "reading "+name+" through "+dockerProxyRepository)
96			}
97			if have != img.Digest {
98				return &BenchError{Kind: SeedFailed, Cause: dockerProxyRepository + " serves another content for " + name, Check: resetCheck}
99			}
100		}
101		_, _ = fmt.Fprintln(out, "restore: "+dockerProxyRepository+" serves the cached images")
102		return nil
103	}
104

1	package nexusbench
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"net/http"
9		"net/url"
10		"slices"
11	)
12	
13	// benchRepositories are the only repositories reset may delete, in the order it
14	// deletes them: the group first, as it names the two others.
15	var benchRepositories = []string{dockerGroupRepository, dockerProxyRepository, dockerHostedRepository}
16	
17	// repositoryPath is the path of one repository, whatever its kind.
18	func repositoryPath(name string) string { return restAPI + "/repositories/" + name }
19	
20	// deleteRepository deletes one of benchRepositories. A repository that is not
21	// there is existed == false without an error. Any other name is refused before
22	// a request is sent: the bench never deletes what it did not create.
23	func (c *client) deleteRepository(ctx context.Context, name string) (existed bool, err error) {
24		if !slices.Contains(benchRepositories, name) {
25			return false, errors.New("refused to delete a repository that is not one of the bench")
26		}
27		op := "delete the repository " + name
28		resp, err := c.do(ctx, request{op: op, method: http.MethodDelete, path: repositoryPath(name)})
29		if err != nil {
30			return false, err
31		}
32		switch {
33		case resp.status == http.StatusNotFound:
34			return false, nil
35		case resp.status < 200 || resp.status > 299:
36			return false, &APIError{Op: op, Status: resp.status}
37		}
38		return true, nil
39	}
40	
41	// invalidatableRepositories are the only repositories invalidateCache may empty:
42	// the proxy and the group of the bench. A hosted repository has no cache.
43	var invalidatableRepositories = []string{dockerGroupRepository, dockerProxyRepository}
44	
45	// invalidateCache empties the cache of the proxy or the group of the bench, the
46	// negative entries included. Any other name is refused before a request is sent,
47	// so that the name never decides the path the admin credentials are sent to.
48	func (c *client) invalidateCache(ctx context.Context, name string) error {
49		if !slices.Contains(invalidatableRepositories, name) {
50			return errors.New("refused to empty the cache of a repository that is not the proxy or the group of the bench")
51		}
52		_, err := c.expect(ctx, request{
53			op: "invalidate the cache of " + name, method: http.MethodPost, path: repositoryPath(name) + "/invalidate-cache",
54		})
55		return err
56	}
57	
58	// unblockProxy puts docker-proxy back in service after its upstream came back:
59	// it sends again the configuration Provision writes (never one read back from the
60	// instance), which lifts the automatic block, then invalidates the cache. A
61	// proxy that does not exist is an error: up creates it.
62	func (c *client) unblockProxy(ctx context.Context, p Params) error {
63		return c.unblockProxyFrom(ctx, repositorySpecs(p))
64	}
65	
66	// unblockProxyFrom is unblockProxy with the specifications it sends. Without
67	// one for docker-proxy it fails before any request: skipping the write and
68	// invalidating the cache would report a success that changed nothing.
69	func (c *client) unblockProxyFrom(ctx context.Context, specs []repositorySpec) error {
70		i := slices.IndexFunc(specs, func(spec repositorySpec) bool { return spec.name == dockerProxyRepository })
71		if i < 0 {
72			return &BenchError{
73				Kind:  ProvisionFailed,
74				Cause: "the bench has no specification for the proxy repository " + dockerProxyRepository,
75				Check: "this is a defect of the bench: report it, with the output of `mise run nexus-bench:render`",
76			}
77		}
78		path := dockerReposPath + "/proxy/" + dockerProxyRepository
79		found, err := c.get(ctx, "read the proxy repository "+dockerProxyRepository, path, nil, nil)
80		if err != nil {
81			return err
82		}
83		if !found {
84			return &BenchError{
85				Kind:  ProvisionFailed,
86				Cause: "the proxy repository " + dockerProxyRepository + " does not exist",
87				Check: upCheck,
88			}
89		}
90		if err := c.write(ctx, "update the proxy repository "+dockerProxyRepository, http.MethodPut, path, specs[i].config); err != nil {
91			return err
92		}
93		return c.invalidateCache(ctx, dockerProxyRepository)
94	}
95	
96	// requireAdmin makes one read as admin, so that a stored password the instance
97	// refuses stops the caller before it changes anything.
98	func (c *client) requireAdmin(ctx context.Context) error {
99		op := "check the admin account"
100		_, err := c.get(ctx, op, usersPath, url.Values{"userId": {adminUserID}}, nil)
101		var api *APIError
102		if errors.As(err, &api) && (api.Status == http.StatusUnauthorized || api.Status == http.StatusForbidden) {
103			return &BenchError{
104				Kind:  ProvisionFailed,
105				Cause: "Nexus refused the stored admin password, so nothing was changed",
106				Check: "the password in the secrets file may not match the instance; run `mise run nexus-bench:down` then `mise run nexus-bench:up`",
107				Err:   err,
108			}
109		}
110		return err
111	}
112	
113	// UnblockProxy puts docker-proxy back in service after its upstream came back:
114	// the configuration Provision writes, sent again, then its cache invalidated.
115	// It uses the stored admin password and nothing else, and refuses an upstream
116	// the bench did not deploy before any request. Every failure is a *BenchError.
117	// A nil out discards the progress lines.
118	func UnblockProxy(ctx context.Context, store SecretStore, baseURL string, p Params, out io.Writer) error {
119		if out == nil {
120			out = io.Discard
121		}
122		if !p.UpstreamIsBench() {
123			return customUpstreamError(p)
124		}
125		if err := requireLoopbackBase(baseURL); err != nil {
126			return err
127		}
128		c, _, err := adminFromStore(ctx, baseURL, store)
129		if err != nil {
130			return asBenchError(err, p, baseURL)
131		}
132		defer c.closeIdle()
133		return putProxyBack(ctx, c, baseURL, p, out)
134	}
135	
136	// putProxyBack is the request side of UnblockProxy, on a client the caller owns,
137	// with the progress lines.
138	func putProxyBack(ctx context.Context, c *client, baseURL string, p Params, out io.Writer) error {
139		_, _ = fmt.Fprintln(out, "restore: putting "+dockerProxyRepository+" back in service")
140		if err := c.unblockProxy(ctx, p); err != nil {
141			return asBenchError(err, p, baseURL)
142		}
143		_, _ = fmt.Fprintln(out, "restore: "+dockerProxyRepository+" is back in service, its cache invalidated")
144		return nil
145	}
146	
147	// requireLoopbackBase refuses a REST origin whose host is not 127.0.0.1 or ::1,
148	// before a request carries the admin credentials to it: Nexus answers in plain
149	// HTTP, and what a restore or a reset does is local to the machine that runs the
150	// port-forwards. "localhost" is refused, as loopbackRegistry refuses it: a name
151	// resolves through the configuration of the host. The host is parsed, so that
152	// "127.0.0.1@evil.example" and "127.0.0.1.evil.example" are not the loopback.
153	func requireLoopbackBase(baseURL string) error {
154		if u, err := url.Parse(baseURL); err == nil && slices.Contains([]string{"127.0.0.1", "::1"}, u.Hostname()) {
155			return nil
156		}
157		return &BenchError{
158			Kind:  Unclassified,
159			Cause: "the REST origin is not on the loopback, and the admin credentials are sent in clear text, so this command does not send them there",
160			Check: "run this command on the machine that runs the bench, or leave the REST host at its default (127.0.0.1)",
161		}
162	}
